// Writes src/envelope-tool.ts from clients/envelope.mjs, so the Worker serves
// the same bytes the repository holds. test/envelope-tool.test.ts fails when
// the two differ: run `node scripts/embed-envelope-tool.mjs` after editing the tool.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const source = readFileSync(fileURLToPath(new URL("../clients/envelope.mjs", import.meta.url)), "utf8");
const out =
  "// GENERATED by scripts/embed-envelope-tool.mjs from clients/envelope.mjs. Do not edit here.\n" +
  "// The Worker serves this string at /tools/envelope.mjs; a test pins it to the file.\n" +
  "export const ENVELOPE_TOOL_SOURCE: string = " +
  JSON.stringify(source) +
  ";\n";
writeFileSync(fileURLToPath(new URL("../src/envelope-tool.ts", import.meta.url)), out);
process.stdout.write(`src/envelope-tool.ts written: ${Buffer.byteLength(source)} bytes of tool\n`);
